toad_implementation.code_blueprint:
canvas {
  size: 960px 540px;
  fill: #0F172A;
  font-family: "Inter, sans-serif";
}

>brandBlue = #3B82F6;
>mintSuccess = #10B981;
>cardSurface = #1E293B;
>borderSubtle = #334155;
>textWhite = #F8FAFC;
>textDim = #94A3B8;

rect #headerBar {
  at: top left of canvas offset 40px 32px;
  size: 880px 48px;
  fill: none;
}

text #companyTitle {
  at: left of #headerBar;
  content: "CLOUDSCALE // ALL-HANDS TELEMETRY";
  font-size: 16px;
  font-weight: 700;
  color: >textWhite;
}

rect #statusBadge {
  at: right of #headerBar;
  size: 140px 32px;
  fill: alpha(>mintSuccess, 0.15);
  stroke: >mintSuccess;
  stroke-width: 1px;
  radius: 16px;
}

text #statusBadgeLabel {
  at: center of #statusBadge;
  content: "● 99.99% UPTIME";
  font-size: 11px;
  font-weight: 600;
  color: >mintSuccess;
}

rect #kpiCard1 {
  at: below #headerBar offset 24px;
  size: 424px 360px;
  fill: >cardSurface;
  stroke: >borderSubtle;
  stroke-width: 1px;
  radius: 12px;
}

text #kpi1Title {
  at: top left of #kpiCard1 offset 24px 24px;
  content: "ACTIVE CLUSTER NODES";
  font-size: 12px;
  font-weight: 600;
  color: >textDim;
}

text #kpi1Value {
  at: below #kpi1Title offset 16px;
  content: "1,420";
  font-size: 48px;
  font-weight: 700;
  color: >brandBlue;
}

text #kpi1Note {
  at: below #kpi1Value offset 12px;
  size: 370px;
  content: "Globales Kubernetes Mesh über 4 Regionen verteilt ohne Lastspitzen.";
  font-size: 13px;
  color: >textDim;
}

rect #kpiCard2 {
  at: right of #kpiCard1 offset 32px;
  size: 424px 360px;
  fill: >cardSurface;
  stroke: >borderSubtle;
  stroke-width: 1px;
  radius: 12px;
}

text #kpi2Title {
  at: top left of #kpiCard2 offset 24px 24px;
  content: "SPRINT MILESTONES";
  font-size: 12px;
  font-weight: 600;
  color: >textDim;
}

text #kpi2Value {
  at: below #kpi2Title offset 16px;
  content: "18 / 20";
  font-size: 48px;
  font-weight: 700;
  color: >mintSuccess;
}

text #kpi2Note {
  at: below #kpi2Value offset 12px;
  size: 370px;
  content: "Sprint 42 steht kurz vor dem Release. Team-Feier am Freitag um 17:00 Uhr!";
  font-size: 13px;
  color: >textDim;
}
